# The recoloring task - let me analyze connectivity in the OUTPUT

def get_neighbors(i, j):
    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
        ni, nj = i+di, j+dj
        if 0 <= ni < 7 and 0 <= nj < 7:
            yield ni, nj

def print_region(cells, name):
    print(f"\n{name}:")
    print(f"  Count: {len(cells)}")
    print(f"  Cells: {cells}")

    # Check if internally connected
    if not cells:
        print("  Internally connected: N/A")
        return

    visited = set()
    stack = [cells[0]]
    count = 0
    while stack:
        i, j = stack.pop()
        if (i,j) in visited: continue
        visited.add((i,j))
        count += 1
        for ni, nj in get_neighbors(i,j):
            if (ni,nj) in cells and (ni,nj) not in visited:
                stack.append((ni,nj))
    print(f"  Internally connected: {count == len(cells)}")

demo_output = [
    [0, 0, 1, 1, 0, 0, 0],
    [3, 3, 1, 1, 4, 0, 0],
    [0, 3, 2, 0, 4, 4, 0],
