# Let me debug the distance computation

def get_neighbors(i, j):
    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
        ni, nj = i+di, j+dj
        if 0 <= ni < 7 and 0 <= nj < 7:
            yield ni, nj

def compute_distances(cells):
    from collections import deque

    # Find boundary cells
    boundary = []
    for i, j in cells:
        is_boundary = False
        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = i+di, j+dj
            if (ni, nj) in cells:
                is_boundary = True
                break
        if not is_boundary:
            boundary.append((i, j))

    # BFS from boundary
    distances = {}
    for cell in cells:
        distances[cell] = float('inf')

    for cell in boundary:
        distances[cell] = 0

    queue = deque(boundary)

    while queue:
        cell = queue.popleft()
        dist = distances[cell]
        for ni, nj in get_neighbors(cell[0], cell[1]):
            if (ni, nj) in cells and distances[(ni, nj)] == float('inf'):
                distances[(ni, nj)] = dist + 1
                queue.append((ni, nj))

    return distances

