def remove_and_check(shape, cell):
    """Check if removing cell disconnects the shape."""
    shape_remain = shape - {cell}
    if len(shape_remain) == 0:
        return True, shape_remain

    # Start BFS from first cell
    start = next(iter(shape_remain))
    visited = {start}
    queue = [start]

    while queue:
        curr = queue.pop(0)
        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = curr[0]+di, curr[1]+dj
            neighbor = (nr, nc)
            if neighbor in shape_remain and neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return len(visited) == len(shape_remain), visited, len(visited)

